        $property->area ? '📐 المساحة: '.number_format((float) $property->area).' م²' : null,
        '💰 السعر: '.number_format((float) $property->price).' '.$property->currency,
        '',
        filled($property->description) ? Str::limit(strip_tags($property->description), 300) : null,
        '',
        'لجميع الصور والتفاصيل:',
        $facebookUrl,
        '',
        filled($shop->phone) ? '📞 '.$shop->phone : null,
        filled($shop->whatsapp) ? '💬 واتساب: '.$shop->whatsapp : null,
